package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.PaymentOrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.Optional;

/** JDBC adapter of the port PaymentOrderRepository (Oracle). */
@Repository
public class JdbcPaymentOrderRepository implements PaymentOrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcPaymentOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
        return jdbcTemplate.query(
                "SELECT order_number, company_id, status, payment_date, commission "
                        + "FROM payment_order WHERE order_number = ? AND company_id = ? "
                        + "FETCH FIRST 1 ROWS ONLY",
                rs -> {
                    if (!rs.next()) {
                        return Optional.<PaymentOrder>empty();
                    }
                    int number = rs.getInt("order_number");
                    Integer orderNo = rs.wasNull() ? null : number;
                    int company = rs.getInt("company_id");
                    Integer companyNo = rs.wasNull() ? null : company;
                    Timestamp ts = rs.getTimestamp("payment_date");
                    return Optional.of(new PaymentOrder(
                            orderNo,
                            companyNo,
                            rs.getString("status"),
                            ts == null ? null : ts.toLocalDateTime(),
                            rs.getBigDecimal("commission")));
                },
                orderNumber, companyId);
    }

